        public static string GetAddress<TEnum>(TEnum value)
            where TEnum : struct, Enum
        {
            object boxed = value;
            if (boxed is Animations AnimationsValue)
            {
                return AnimationsValue.ToAddress();
            }

            if (boxed is Auto_Packages_com_unity_render_pipelines_core Auto_Packages_com_unity_render_pipelines_coreValue)
            {
                return Auto_Packages_com_unity_render_pipelines_coreValue.ToAddress();
            }

            if (boxed is Auto_Packages_com_unity_render_pipelines_universal Auto_Packages_com_unity_render_pipelines_universalValue)
            {
                return Auto_Packages_com_unity_render_pipelines_universalValue.ToAddress();
            }

            if (boxed is Images ImagesValue)
            {
                return ImagesValue.ToAddress();
            }

            if (boxed is Prefabs PrefabsValue)
            {
                return PrefabsValue.ToAddress();
            }

            if (boxed is ScriptableObjectDatas ScriptableObjectDatasValue)
            {
                return ScriptableObjectDatasValue.ToAddress();
            }

            if (boxed is SpriteLibrarys SpriteLibrarysValue)
            {
                return SpriteLibrarysValue.ToAddress();
            }

            if (boxed is Tiles TilesValue)
            {
                return TilesValue.ToAddress();
            }

            throw new ArgumentException($"지원하지 않는 Addressable enum 타입입니다: {typeof(TEnum).FullName}", nameof(value));
        }
